<template><section v-if="specialists.length" class="hired-specialists" data-i18n-skip><header><h3 class="bz-h3">{{ $ui('Hired Specialists') }}</h3><span class="bz-meta">{{ $ui('Access per approved job') }}</span></header><div class="hired-specialists__grid"><button v-for="specialist in specialists" :key="specialist.agentId" type="button" @click="$emit('open-market')"><span class="material-symbols-outlined" aria-hidden="true">person_search</span><span><strong>{{ specialist.agentName }}</strong><small>{{ specialist.terms.serviceOffer.title }}</small><small>{{ specialist.terms.serviceOffer.assets.map(a=>a.title).join(' · ') }}</small></span><span class="material-symbols-outlined" aria-hidden="true">arrow_forward</span></button></div></section></template>
<script setup>
import {ref,onMounted,onBeforeUnmount,watch} from 'vue';
import {listSmartAgentJobs} from '../../services/smartAgentJobs.service.js';
const props=defineProps({companyId:{type:String,required:true}});defineEmits(['open-market']);const specialists=ref([]);let revision=0;
async function refresh(){const version=++revision;try{const records=await listSmartAgentJobs(props.companyId);if(version!==revision)return;const distinct=new Map();for(const record of [...records].sort((a,b)=>b.createdAt-a.createdAt)){if(record.terms?.serviceOffer && !['failed','pending'].includes(record.status) && !distinct.has(record.agentId)) distinct.set(record.agentId,record);}specialists.value=[...distinct.values()];}catch{if(version===revision)specialists.value=[];}}
watch(()=>props.companyId,refresh,{immediate:true});onMounted(()=>window.addEventListener('bonzai:smart-agent-job',refresh));onBeforeUnmount(()=>{revision++;window.removeEventListener('bonzai:smart-agent-job',refresh);});
</script>
<style scoped>
.hired-specialists{display:grid;gap:16px;margin-bottom:24px}.hired-specialists header{display:flex;flex-wrap:wrap;gap:12px;align-items:center;justify-content:space-between}.hired-specialists h3{margin:0}.hired-specialists__grid{display:grid;grid-template-columns:repeat(auto-fit,minmax(min(300px,100%),1fr));gap:12px}.hired-specialists button{display:flex;align-items:center;gap:14px;text-align:left;padding:20px;color:var(--bz-fg);background:var(--bz-panel);border:1px solid var(--bz-border);border-radius:var(--bz-r-md);cursor:pointer}.hired-specialists button>span:nth-child(2){min-width:0;flex:1}.hired-specialists strong,.hired-specialists small{display:block;overflow-wrap:anywhere}.hired-specialists small{color:var(--bz-fg-mid);margin-top:5px}.hired-specialists .material-symbols-outlined{color:var(--bz-accent)}.hired-specialists button:hover{border-color:var(--bz-accent)}
</style>
